def conv2d_batch(self, kernel, batch, channels, filters, height, width,
                 size, groups=1, bias=None, stride=1, padding=0,
                 dilation=1):
    if not isinstance(kernel, Tensor):
        raise TypeError("kernel must be a Tensor")
    if bias is not None and not isinstance(bias, Tensor):
        raise TypeError("bias must be a Tensor or None")
    # Both operands must hold non-empty 1D finite float lists; data may
    # have been mutated after construction, so re-validate at call time.
    x_data = _require_nonempty_float_vector(self, "conv2d_batch")
    w_data = _require_nonempty_float_vector(kernel, "conv2d_batch")
    b_data = None
    if bias is not None:
        b_data = _require_nonempty_float_vector(bias, "conv2d_batch")
    # batch, channels, filters, height, width, size, groups, stride
    # and dilation must be non-bool positive ints, and padding a
    # non-bool non-negative int.
    for name, value in (
        ("batch", batch),
        ("channels", channels),
        ("filters", filters),
        ("height", height),
        ("width", width),
        ("size", size),
        ("groups", groups),
        ("stride", stride),
        ("dilation", dilation),
    ):
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError(name + " must be a positive int")
        if value <= 0:
            raise ValueError(name + " must be a positive int")
    if isinstance(padding, bool) or not isinstance(padding, int):
        raise TypeError("padding must be a non-negative int")
    if padding < 0:
        raise ValueError("padding must be a non-negative int")
    B, C, O, H, W, K, G, S, P, D = (
        batch, channels, filters, height, width, size, groups,
        stride, padding, dilation,
    )
    # Groups partition the channels and filters into G disjoint blocks;
    # both counts must divide evenly for the split to be well defined.
    if C % G != 0 or O % G != 0:
        raise ValueError(
            "groups must evenly divide channels and filters"
        )
    CPG = C // G
    FPG = O // G
    # self stores B images of C channels of H x W pixels and kernel O
    # filters of C/G channels of K x K weights, all in row-major order.
    if len(x_data) != B * C * H * W:
        raise ValueError(
            "conv2d_batch input length must equal "
            "batch * channels * height * width"
        )
    kernel_len = O * CPG * K * K
    if len(w_data) != kernel_len:
        if G == 1:
            raise ValueError(
                "conv2d_batch kernel length must equal "
                "filters * channels * size * size"
            )
        raise ValueError(
            "conv2d_batch kernel length must equal "
            "filters * (channels // groups) * size * size"
        )
    # The bias holds one trainable offset per output channel.
    if b_data is not None and len(b_data) != O:
        raise ValueError(
            "conv2d_batch bias length must equal filters"
        )
    # Dilation spaces the kernel taps by D, so the effective receptive
    # field spans E = D*(K-1)+1 positions; with D=1 this is simply K.
    E = D * (K - 1) + 1
    out_h = (H + 2 * P - E) // S + 1
    out_w = (W + 2 * P - E) // S + 1
    if out_h <= 0 or out_w <= 0:
        raise ValueError(
            "conv2d_batch output dimensions must be positive"
        )
    # Snapshot all operands at call time so later caller-side mutation
    # or replacement of any input can change neither the forward
    # result nor a pending backward pass.
    snapshot_x = list(x_data)
    snapshot_w = list(w_data)
    snapshot_b = list(b_data) if b_data is not None else None
    # Batched grouped multi-channel 2D cross-correlation: the kernel is
    # never flipped. Filter o belongs to group g = o // (O/G) and reads
    # only input channels c0 .. c0+C/G-1, where c0 = g*(C/G). The output
    # is B x O x OH x OW in row-major order; in ascending (b, o, or, oc)
    # order each output starts at bias[o] (0.0 without a bias), then in
    # ascending (cl, kr, kc) order (cl the in-group channel, c = c0+cl)
    # accumulates
    # y[((b*O+o)*OH+or)*OW+oc] += x[((b*C+c)*H+r)*W+q]
    #   * w[((o*(C/G)+cl)*K+kr)*K+kc],
    # with r = or*S+kr*D-P and q = oc*S+kc*D-P; out-of-range input
    # positions from padding are skipped. With G=1, S=1, P=0 and D=1
    # this reduces to dense (b, o, or, oc, c, kr, kc) order. A
    # non-finite product or partial sum aborts before a result tensor
    # exists, so no state can change.
    out_len = B * O * out_h * out_w
    out_data = [0.0] * out_len
    for b in range(B):
        for o in range(O):
            g = o // FPG
            c0 = g * CPG
            bias_o = snapshot_b[o] if snapshot_b is not None else 0.0
            for orow in range(out_h):
                for ocol in range(out_w):
                    oi = ((b * O + o) * out_h + orow) * out_w + ocol
                    acc = bias_o
                    for cl in range(CPG):
                        c = c0 + cl
                        for kr in range(K):
                            r = orow * S + kr * D - P
                            if not 0 <= r < H:
                                continue
                            for kc in range(K):
                                q = ocol * S + kc * D - P
                                if not 0 <= q < W:
                                    continue
                                xi = (
                                    ((b * C + c) * H + r) * W + q
                                )
                                wi = ((o * CPG + cl) * K + kr) * K + kc
                                product = snapshot_x[xi] * snapshot_w[wi]
                                if not math.isfinite(product):
                                    raise ValueError(
                                        "conv2d_batch intermediate must"
                                        " be finite"
                                    )
                                acc = acc + product
                                if not math.isfinite(acc):
                                    raise ValueError(
                                        "conv2d_batch intermediate must"
                                        " be finite"
                                    )
                    out_data[oi] = acc
    needs_grad = self.requires_grad or kernel.requires_grad
    if bias is not None and bias.requires_grad:
        needs_grad = True
    if not needs_grad:
        return Tensor._make(
            out_data, False, (), None,
            grad_validator=lambda g: _validate_vector_grad(g, out_len),
        )
    parent_self, parent_kernel = self, kernel
    parent_bias = bias

    def backward_fn(grad):
        # dx[xi] += g*w[wi] and dw[wi] += g*x[xi], accumulated from
        # 0.0 in the same ascending (b, o, or, oc, cl, kr, kc) order,
        # indexing and group-channel mapping as the forward pass, with
        # the same dilated r/q computation and out-of-range skip; dw
        # has no batch index, so its contributions reduce across all B
        # images. db[o] += g reduces in ascending (b, or, oc) order per
        # filter. A non-finite product or partial sum aborts the whole
        # pass before any grad is written.
        dx = [0.0] * (B * C * H * W)
        dw = [0.0] * (O * CPG * K * K)
        db = [0.0] * O if snapshot_b is not None else None
        for b in range(B):
            for o in range(O):
                g = o // FPG
                c0 = g * CPG
                for orow in range(out_h):
                    for ocol in range(out_w):
                        gv = grad[
                            ((b * O + o) * out_h + orow) * out_w + ocol
                        ]
                        if db is not None:
                            db[o] = db[o] + gv
                            if not math.isfinite(db[o]):
                                raise ValueError(
                                    "conv2d_batch backward "
                                    "intermediate must be finite"
                                )
                        for cl in range(CPG):
                            c = c0 + cl
                            for kr in range(K):
                                r = orow * S + kr * D - P
                                if not 0 <= r < H:
                                    continue
                                for kc in range(K):
                                    q = ocol * S + kc * D - P
                                    if not 0 <= q < W:
                                        continue
                                    xi = (
                                        ((b * C + c) * H + r) * W + q
                                    )
                                    wi = (
                                        ((o * CPG + cl) * K + kr) * K
                                        + kc
                                    )
                                    contrib_x = gv * snapshot_w[wi]
                                    if not math.isfinite(contrib_x):
                                        raise ValueError(
                                            "conv2d_batch backward "
                                            "intermediate must be finite"
                                        )
                                    dx[xi] = dx[xi] + contrib_x
                                    if not math.isfinite(dx[xi]):
                                        raise ValueError(
                                            "conv2d_batch backward "
                                            "intermediate must be finite"
                                        )
                                    contrib_w = gv * snapshot_x[xi]
                                    if not math.isfinite(contrib_w):
                                        raise ValueError(
                                            "conv2d_batch backward "
                                            "intermediate must be finite"
                                        )
                                    dw[wi] = dw[wi] + contrib_w
                                    if not math.isfinite(dw[wi]):
                                        raise ValueError(
                                            "conv2d_batch backward "
                                            "intermediate must be finite"
                                        )
        # The same object may play several roles; merge such roles into
        # one contribution per tensor, and submit only parents that
        # require grad.
        merged = {}
        roles = [
            (parent_self, dx),
            (parent_kernel, dw),
        ]
        if parent_bias is not None:
            roles.append((parent_bias, db))
        for parent, value in roles:
            if not parent.requires_grad:
                continue
            entry = merged.get(id(parent))
            if entry is None:
                merged[id(parent)] = [parent, value]
            else:
                combined = _merge_grad(entry[1], value)
                _ensure_finite_grad(combined)
                entry[1] = combined
        return [(entry[0], entry[1]) for entry in merged.values()]

    parents = (parent_self, parent_kernel)
    if parent_bias is not None:
        parents = parents + (parent_bias,)
    return Tensor._make(
        out_data, True, parents, backward_fn,
        grad_validator=lambda g: _validate_vector_grad(g, out_len),
    )

def max_pool1d(self, kernel_size, stride=None, padding=0, dilation=1):
    data = _require_nonempty_float_vector(self, "max_pool1d")
    if isinstance(kernel_size, bool) or not isinstance(kernel_size, int):
        raise TypeError("kernel_size must be a positive int")
    if kernel_size <= 0:
        raise ValueError("kernel_size must be a positive int")
    if stride is None:
        stride = kernel_size
    elif isinstance(stride, bool) or not isinstance(stride, int):
        raise TypeError("stride must be a positive int")
    elif stride <= 0:
        raise ValueError("stride must be a positive int")
    if isinstance(padding, bool) or not isinstance(padding, int):
        raise TypeError("padding must be a non-negative int")
    if padding < 0:
        raise ValueError("padding must be a non-negative int")
    if isinstance(dilation, bool) or not isinstance(dilation, int):
        raise TypeError("dilation must be a positive int")
